import{_ as t,o as i,c as a,a2 as s}from"./chunks/framework.Y8If66rx.js";const b=JSON.parse('{"title":"Accessibility and testing","description":"","frontmatter":{},"headers":[],"relativePath":"guide/accessibility-testing.md","filePath":"guide/accessibility-testing.md"}'),o={name:"guide/accessibility-testing.md"};function r(n,e,l,c,d,u){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="accessibility-and-testing" tabindex="-1">Accessibility and testing <a class="header-anchor" href="#accessibility-and-testing" aria-label="Permalink to &quot;Accessibility and testing&quot;">​</a></h1><h2 id="accessibility-behavior-in-the-package" tabindex="-1">Accessibility behavior in the package <a class="header-anchor" href="#accessibility-behavior-in-the-package" aria-label="Permalink to &quot;Accessibility behavior in the package&quot;">​</a></h2><ul><li><code>ResizableTable</code> requires a <code>label</code>, applied as the table&#39;s accessible name.</li><li><code>TableSortControls</code> renders a labeled select and direction button in a sorting group. Its label defaults to <code>&quot;Sort by&quot;</code>; the group name is <code>&quot;Table sorting&quot;</code>.</li><li>Sorted headers expose <code>aria-sort</code>.</li><li>Each resize separator has <code>role=&quot;separator&quot;</code>, a generated label, vertical orientation, current value, and keyboard support. Arrow keys resize by 2 pixels, Shift+Arrow by 10 pixels, and Home/End move to the available bounds.</li><li>Virtualized tables include row counts and indexes. A focused rendered row is retained while the virtual range changes.</li><li>Table primitives use native table elements and expose stable <code>data-slot</code> attributes for styling.</li></ul><h2 id="consumer-responsibilities" tabindex="-1">Consumer responsibilities <a class="header-anchor" href="#consumer-responsibilities" aria-label="Permalink to &quot;Consumer responsibilities&quot;">​</a></h2><ul><li>Provide a meaningful <code>label</code> for every <code>ResizableTable</code>.</li><li>Use text headers for sortable columns so the sorting selector has useful labels. If custom column header renderers are used, verify the generated separator labels with assistive technology.</li><li><code>getRowProps</code> only forwards row attributes and handlers. It does not add keyboard activation or selection behavior. Prefer native interactive controls in cells, or implement and test the complete keyboard interaction when rows themselves are interactive.</li><li>Set <code>aria-selected</code> only when the row actually represents a selectable selection state. Styling the selected state does not implement selection.</li><li>Test virtualized tables with the actual assistive technology and browser combinations your product supports. Only rendered rows are present in the DOM at a given scroll position.</li><li>Check focus visibility, contrast, zoom, narrow viewports, and right-to-left direction in the consuming theme.</li><li>If a cell contains a canvas-based visualization such as <code>@lego/graphs</code> Gantt, provide an equivalent text label or summary. Canvas graphics do not become meaningful table text automatically. See the <a href="./gantt-column.html">Gantt-column guide</a>.</li></ul><h2 id="suggested-consumer-tests" tabindex="-1">Suggested consumer tests <a class="header-anchor" href="#suggested-consumer-tests" aria-label="Permalink to &quot;Suggested consumer tests&quot;">​</a></h2><p>Use the test runner already established by your application; this package doesn&#39;t prescribe or ship a test framework.</p><ol><li>Render representative rows and assert their values and table accessible name.</li><li>Select a sort column, verify the row order, toggle direction, then choose <strong>Unsorted</strong>.</li><li>Focus a resize separator and test Arrow, Shift+Arrow, Home, and End while asserting the target and any partner stay within configured bounds. Verify independent pixel resizing and proportional scaling after a percentage drag.</li><li>Test row callbacks and selection attributes in the feature module.</li><li>If testing virtualization in a DOM emulator, provide the environment&#39;s normal <code>ResizeObserver</code> and geometry support or mock them narrowly; then verify rendered range, row indexes, and focus retention.</li><li>Build the production app to verify the stylesheet export and CSS custom properties are included.</li></ol><p>Run <code>npm test</code> for pure sizing regressions, including weighted constraints, fixed columns, fallback selection, and post-resize scaling. The exported <code>resizeColumnPair</code> utility can also be tested in a consumer&#39;s existing setup. Use a real browser for pointer capture, RTL, commit timing, and chart alignment; see the <a href="./column-sizing.html">sizing contract</a>.</p>',9)])])}const p=t(o,[["render",r]]);export{b as __pageData,p as default};
